+    fn discover_root_recursive(
+        &self,
+        root: &SkillRoot,
+    ) -> anyhow::Result<Vec<SkillCandidate>> {
+        if !root.path.exists() {
+            return Ok(Vec::new());
+        }
+        let root_path = fs::canonicalize(&root.path)
+            .with_context(|| format!("canonicalize skill root {}", root.path.display()))?;
+        let mut candidates = Vec::new();
+        let mut visited = 0usize;
+        self.walk_recursive(
+            &root_path,
+            &root_path,
+            root,
+            0,
+            &mut visited,
+            &mut candidates,
+        )?;
+        Ok(candidates)
+    }
+
+    fn walk_recursive(
+        &self,
+        root_path: &Path,
+        directory: &Path,
+        root: &SkillRoot,
+        depth: usize,
+        visited: &mut usize,
+        candidates: &mut Vec<SkillCandidate>,
+    ) -> anyhow::Result<()> {
+        if depth > MAX_RECURSIVE_SKILL_DEPTH || *visited >= MAX_RECURSIVE_SKILL_ENTRIES {
+            return Ok(());
+        }
+        for entry in fs::read_dir(directory)
+            .with_context(|| format!("read skill directory {}", directory.display()))?
+        {
+            if *visited >= MAX_RECURSIVE_SKILL_ENTRIES {
+                break;
+            }
+            *visited += 1;
+            let entry = entry?;
+            let file_type = entry.file_type()?;
+            if file_type.is_symlink() {
+                continue;
+            }
+            let path = entry.path();
+            if file_type.is_dir() {
+                let canonical = match fs::canonicalize(&path) {
+                    Ok(path) if path.starts_with(root_path) => path,
+                    _ => continue,
+                };
+                let bundled = canonical.join("SKILL.md");
+                if bundled.is_file() {
+                    match parse_candidate(&bundled, &root.source, &self.name, root.rank) {
+                        Ok(candidate) => candidates.push(candidate),
+                        Err(error) => eprintln!(
+                            "ignoring invalid skill {}: {error:#}",
+                            bundled.display()
+                        ),
+                    }
+                }
+                self.walk_recursive(
+                    root_path,
+                    &canonical,
+                    root,
+                    depth + 1,
+                    visited,
+                    candidates,
+                )?;
+            } else if depth == 0
+                && file_type.is_file()
+                && path.extension().and_then(|value| value.to_str()) == Some("md")
+            {
+                match parse_candidate(&path, &root.source, &self.name, root.rank) {
+                    Ok(candidate) => candidates.push(candidate),
+                    Err(error) => {
+                        eprintln!("ignoring invalid skill {}: {error:#}", path.display())
+                    }
+                }
+            }
+        }
+        Ok(())
+    }
